import {getScenarioMapping, scenarioMappingHtml, mappingDirectoryHtml} from './scenario-mapping.mjs';
import {workshopFlow,workshopTools,bindFlowEditor} from './flow-editor.mjs?v=3';
import {content as C} from './content.mjs';
import {connections as LINKS} from './connections.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const P=Object.fromEntries(C.parents.map(p=>[p.parent_ref,p])),A=Object.fromEntries(C.actions.map(a=>[a.action_ref,a])),R=Object.fromEntries(C.references.map(r=>[r.id,r]));
const stages=['Initiate','Determine','Assess','Resolve','Clear'],process=['M0','M1','M2','M3','M4','M5','M6','M7','M8'];
const processNames=['Booking context','Intake','Requirements','Evidence','Screening','Enhanced review','Quality review','Conflicts','Readiness'];
const symbols={retain:'=',remove:'−',enhance:'↑',add:'+',unconfirmed:'?'},labels={retain:'Retain',remove:'Remove',enhance:'Enhance',add:'Add',unconfirmed:'Under review'};
const heroBeats=[
 {title:'Establish the relationship',stage:'Initiate',scene:'SCN-ENTITY',people:['PERSONA-RM','PERSONA-CLIENT-T'],text:'Entity A in Australia requests an FX forward relationship. Entity B in Singapore is the reported parent. Person T works for B and says they coordinate information for A.',question:'What can Person T do for Entity A?',wait:'Specific authority for A is not established.',next:['SCN-SCOPE','SCN-ENTITY']},
 {title:'Ask for what is missing',stage:'Determine',scene:'SCN-GAP',people:['PERSONA-KYCOPS','PERSONA-RM','PERSONA-CLIENT-T'],text:'The team checks what information can be reused, identifies the remaining question and prepares a permitted request. Person T contributes only to the items they are allowed to access.',question:'Does the request make sense to the person receiving it?',wait:'A saved or submitted response still needs the appropriate review.',next:['SCN-REQUIREMENTS','SCN-SOURCE','SCN-GAP','SCN-VALIDATE']},
 {title:'Review the possible match',stage:'Assess',scene:'SCN-MATCH',people:['PERSONA-KYCOPS','PERSONA-RISK'],text:'The same Person T appears in a possible screening match. The reviewer compares identifying facts and can ask for specific missing evidence before reaching a decision.',question:'Which facts agree, differ or remain unknown?',wait:'Identity evidence and authority to coordinate information answer different questions.',next:['SCN-POPULATION','SCN-MATCH','SCN-EDD']},
 {title:'Coordinate the parallel work',stage:'Resolve',scene:'SCN-LEGAL',people:['PERSONA-CONTROL','PERSONA-CREDIT','PERSONA-LEGAL','PERSONA-QA'],text:'Conflicts can start from intake. Legal and Credit progress on their own inputs; current Credit information can feed the agreement. Quality review asks for a precise correction where needed.',question:'Who is waiting for whom, and what can continue?',wait:'Resolving a screening finding does not close Legal, Credit or Conflicts.',next:['SCN-CONFLICTS','SCN-CREDIT','SCN-LEGAL','SCN-QA']},
 {title:'Explain the overall readiness',stage:'Clear',scene:'SCN-READINESS',people:['PERSONA-CASEMGR','PERSONA-RM'],text:'The case manager brings the applicable prerequisites together. A local decision, the readiness view and recording or communicating an outcome remain distinct.',question:'What still stands between this relationship and readiness?',wait:'This authored case stays open where evidence, conditions or authority are unresolved.',next:['SCN-READINESS','SCN-PUBLISH']}
];
const workshopChapter=v=>Number.isInteger(Number(v))?Math.max(0,Math.min(4,Number(v))):0;
const defaultState=()=>({view:'journey',dimension:'cj',mappingView:'map',mappingStage:'all',mappingQuery:'',workshopChapter:null,scene:null,work:null,action:null,persona:null,reference:null,chapter:0,side:'after',compare:false,tab:'experience',zoom:1,fit:false,query:'',filter:'all',stage:'all',role:'all',direction:'all',execution:'all',principle:'all',process:'all',review:'all',hero:0,mapX:0,mapY:0,windowY:0});
let state=defaultState(),initialized=false,root,controller,bridge={},opener=null,lastUrl='', linkObserver, drawTimer;
const scene=()=>C.scenes.find(s=>s.id===state.scene),person=id=>C.personas.find(p=>p.id===id);
const btn=(text,action,value='',extra='')=>`<button type="button" data-sn="${action}" data-sn-value="${esc(value)}" ${extra}>${text}</button>`;
const portrait=(id,compact=false)=>{const p=person(id);return p?`<span class="sn-person ${compact?'sn-person-compact':''}"><img src="${p.image}" alt="${esc(p.name)} · synthetic portrait" width="44" height="52"><span><b>${esc(p.name)}</b><small>${esc(p.role)}</small></span></span>`:'';};
const searchable=t=>String(t)+' '+(window.CTTLanguage?.translate(String(t))||'');
const trace=id=>`<small class="sn-id">${esc(id)}</small>`;
function legend(){return `<div class="sn-legend" aria-label="Change legend">${['retain','remove','enhance','add'].map(k=>`<span class="sn-key sn-${k}"><b>${symbols[k]}</b>${labels[k]}</span>`).join('')}${btn('About changes','legend','','aria-label="Explain the change legend"')}</div>`;}
function sideButtons(){return `<div class="sn-segment" role="tablist" aria-label="Before and After">${['before','after'].map(s=>btn(s==='before'?'Before':'After','side',s,`role="tab" aria-selected="${state.side===s}" tabindex="${state.side===s?0:-1}"`)).join('')}</div>`;}
function init(){if(initialized)return;initialized=true;const q=new URLSearchParams(location.search);const hash=new URLSearchParams(location.hash.replace(/^#/,''));state={...state,mappingView:'map',mappingStage:['Initiate','Determine','Assess','Resolve','Clear'].includes(q.get('mappingstage'))?q.get('mappingstage'):'all',mappingQuery:q.get('mapquery')||'',dimension:q.get('dimension')==='hero'?'hero':'cj',view:['hero','index','research','product','workshop','flows','fulljourney'].includes(q.get('studio'))?q.get('studio'):'journey',scene:q.get('scenario')||hash.get('scn'),work:q.get('work'),action:q.get('action'),side:q.get('comparison')==='before'?'before':'after',reference:q.get('reference'),persona:q.get('persona')||hash.get('persona'),hero:Math.max(0,Math.min(4,Number(q.get('beat')||0)))};if(state.view==='hero'){state.view='journey';state.workshopChapter=workshopChapter(q.get('beat'));}else if(state.view==='journey'&&q.has('beat'))state.workshopChapter=workshopChapter(q.get('beat'));if(state.action&&A[state.action]){state.work=A[state.action].parent_ref;state.scene=A[state.action].scenario_ref;}if(state.work&&P[state.work])state.scene=P[state.work].scenario_ref;if(state.scene&&!scene())state.error='That scenario was not found. Use the index to locate the work.';if(state.work&&scene())state.chapter=Math.max(0,scene().chapters.findIndex(c=>c.parents.includes(state.work)));if(state.persona&&!person(state.persona))state.persona=null;if(state.reference&&!R[state.reference])state.reference=null;}
export function studioNextHeader(){init();const zh=(window.CTTLanguage?.locale||new URLSearchParams(location.search).get('locale'))==='zh-CN';return `<header class="sn-app-header sn-workshop-header"><a class="sn-wordmark" href="?studio=journey&locale=${zh?'zh-CN':'en-US'}"><span class="sm-brand-mark" aria-hidden="true">CT</span><span class="sm-brand-name">Clear-to-Trade<span>Scenario workspace</span></span></a><nav aria-label="Workshop navigation">${btn('Workshop','view','journey',`aria-current="${state.view==='journey'?'page':'false'}"`)}${btn('Scenario Studio','view','fulljourney',`aria-current="${state.view!=='journey'?'page':'false'}"`)}<a class="sn-demo-link" href="../08_inspire/app/index.html" target="_blank" rel="noopener noreferrer">Demo</a></nav><span class="sn-en">English</span></header>`;}
function viewNav(){if(state.view==='journey')return '';const zh=(window.CTTLanguage?.locale||new URLSearchParams(location.search).get('locale'))==='zh-CN';return `<nav class="sn-view-nav" aria-label="Reference navigation">${[['fulljourney','Full journey','完整旅程'],['index','Scenario index','场景索引'],['flows','Flow library','流程全集'],['workshop','Workshop scorecard','工作坊评分'],['product','Product Prototype','产品原型'],['research','Research','研究']].map(([v,en,cn])=>btn(en,'view',v,`aria-current="${state.view===v?'page':'false'}"`)).join('')}</nav>`;}
function caseIntro(){return `<section class="sn-case-intro"><div><span class="sn-eyebrow">One synthetic case</span><h2>Entity A’s first FX forward relationship</h2><p>Australia · Entity B is the reported parent in Singapore. Person T’s authority for A is still an open question.</p></div>${btn('View hero case <span aria-hidden="true">↗</span>','view','hero','class="sn-primary"')}</section>`;}
function scnButton(s,extra=''){return btn(`<span>${esc(s.title)}</span>${trace(s.id)}${extra}`,'scene',s.id,`class="sn-scenario" aria-label="${esc(s.title)}; ${s.id}; open workflow"`);}
function matrix(){const clients=C.clientTouchpoints;return `<section class="sn-map-section"><div class="sn-map-heading"><div><h2>People and their journey</h2><span class="sn-muted">${state.side==='after'?'The proposed experience':'The current experience'}</span></div><div class="sn-map-tools">${sideButtons()}${btn('Process overview','process')}${legend()}</div></div><label class="sn-mobile-stage">Focus on a stage <select data-sn-change="stage">${['all',...stages].map(s=>`<option value="${s}" ${state.stage===s?'selected':''}>${s==='all'?'All stages':s}</option>`).join('')}</select></label><div class="sn-map-scroll" tabindex="0" aria-label="Journey and persona matrix. Scroll to view all people and process stages."><div class="sn-matrix"><div class="sn-map-header"><div class="sn-axis-label">People</div><div class="sn-stage-band">${stages.map((s,i)=>`<div style="grid-column:span ${i===4?1:2}"><b>${s}</b></div>`).join('')}</div><div class="sn-axis-label sn-axis-sub">Process</div><div class="sn-process-band">${process.map((p,i)=>`<div data-col="${p}">${p}<small>${processNames[i]}</small></div>`).join('')}</div></div>${C.personas.map(p=>{let matches=C.scenes.filter(s=>s.personas.includes(p.id)&&(state.stage==='all'||s.journey_stage===state.stage));const offsets=Object.create(null);return `<div class="sn-lane"><button class="sn-lane-person" data-sn="persona" data-sn-value="${p.id}">${portrait(p.id)}<span class="sn-lane-goal">${esc(p.goal)}</span></button><div class="sn-lane-work">${p.id==='PERSONA-CLIENT-T'?clients.filter(t=>state.side==='before'||!String(t.target_as_drawn_en).toLowerCase().includes('removed')).map((t,i)=>`<div class="sn-touchpoint" style="grid-column:${Math.min(9,({ 'CT-01':1,'CT-02':3,'CT-03':4,'CT-04':5,'CT-05':6,'CT-06':7,'CT-07':8,'CT-08':9})[t.id]||i+1)};grid-row:1">${btn(esc(t.ask_en),'touchpoint',t.id)}<span>${esc(t.waits_for_en)}</span></div>`).join(''):''}${matches.map(s=>{const row=(offsets[s.column]||0)+1+(p.id==='PERSONA-CLIENT-T'?1:0);offsets[s.column]=(offsets[s.column]||0)+1;return `<div data-key="${s.id}|${p.id}" class="sn-span ${s.span>2?'sn-parallel':''}" style="grid-column:${s.column+1}/span ${s.span};grid-row:${row}">${scnButton(s,s.id==='SCN-CONFLICTS'?'<small class="sn-relation">↳ Can start from intake</small>':s.id==='SCN-LEGAL'?'<small class="sn-relation">← Current Credit terms</small>':s.id==='SCN-CREDIT'?'<small class="sn-relation">→ Agreement preparation</small>':'')}</div>`;}).join('')}</div></div>`;}).join('')}<svg class="sn-link-overlay" aria-label="Five typed journey relationships"></svg></div></div><div class="sn-map-foot"><p>Conflicts can begin at intake. Legal and Credit run in parallel on their own inputs.</p>${'<span class="sn-line-legend"><i class="solid"></i>Source handoff <i class="dash"></i>Design loop <i class="dot"></i>Early start</span>'+btn('Read the connections','connections')}</div></section>`;}
function dimensionNav(){return `<nav class="sn-dimension-nav" aria-label="Journey perspective">${btn('Customer journey','dimension','cj',`aria-pressed="${state.dimension!=='hero'}"`)}${btn('Hero case','dimension','hero',`aria-pressed="${state.dimension==='hero'}"`)}</nav>`;}
function heroCaseDimension(){const b=heroBeats[state.hero];const rows=[['PERSONA-CLIENT-T',[['SCN-SCOPE','SCN-ENTITY'],['SCN-SOURCE','SCN-GAP'],['SCN-MATCH','SCN-EDD'],['SCN-QA'],['SCN-PUBLISH']]],['PERSONA-RM',[['SCN-SCOPE','SCN-ENTITY'],[],[],[],['SCN-PUBLISH']]],['PERSONA-CASEMGR',[['SCN-REQUIREMENTS'],['SCN-GAP'],[],[],['SCN-READINESS']]],['PERSONA-KYCOPS',[[],['SCN-SOURCE','SCN-POPULATION'],['SCN-MATCH'],[],[]]],['PERSONA-RISK',[[],[],['SCN-MATCH','SCN-VALIDATE','SCN-EDD'],[],[]]],['PERSONA-LEGAL',[[],[],[],['SCN-LEGAL'],[]]],['PERSONA-CREDIT',[[],[],[],['SCN-CREDIT'],[]]],['PERSONA-CONTROL',[[],[],[],['SCN-CONFLICTS'],[]]],['PERSONA-QA',[[],[],[],['SCN-QA'],[]]]];return `<section class="sn-case-dimension"><div class="sn-case-context"><h2>One Hero Case</h2><p>Entity A · Australia · FX forward. Entity B is the reported parent in Singapore; Person T coordinates information. Specific authority for A remains unconfirmed.</p></div><nav class="sn-case-stages">${heroBeats.map((x,i)=>btn(`${String(i+1).padStart(2,'0')} · ${x.stage}`,'beat',i,`aria-pressed="${i===state.hero}"`)).join('')}</nav><article class="sn-case-beat"><div><span>${b.stage} · ${['M0–M1','M2–M3','M4–M5','M6–M7 · Legal / Credit','M8'][state.hero]}</span><h2>${b.title}</h2><p>${b.text}</p><strong>${b.question}</strong><p>${b.wait}</p></div><aside>${btn('Locate in customer journey','locate-cj',['intake','evidence','screen-decision','legal-start','readiness'][state.hero])}${b.next.map(id=>btn(esc(C.scenes.find(s=>s.id===id).title),'scene',id)).join('')}</aside></article><div class="sn-case-role-map"><div class="sn-case-grid-head"><strong>Key actors</strong>${heroBeats.map(b=>`<strong>${b.stage}</strong>`).join('')}</div>${rows.map(([id,cells])=>`<div class="sn-case-grid-row"><div>${portrait(id,true)}</div>${cells.map((ids,i)=>`<div class="${i===state.hero?'is-stage':''}">${ids.map(id=>btn(esc(C.scenes.find(s=>s.id===id).title),'scene',id)).join('')}</div>`).join('')}</div>`).join('')}</div><p>Local completion ≠ overall readiness</p></section>`;}
function approvedMap(){return `<section class="sm-portal"><div class="sm-view-toolbar">${dimensionNav()}</div><div class="sm-explorer-content"><section class="sn-approved-map sn-map-section sn-hero-journey sm-canvas"><iframe class="sn-approved-frame" title="Interactive target journey" src="./studio-next/${state.dimension==='hero'?'hero-journey':'target-journey'}.html?v=scenario-popup-1&theme=light&locale=${window.CTTLanguage?.locale||'en-US'}${state.locateNode?'#focus='+encodeURIComponent(state.locateNode):''}" scrolling="no"></iframe></section></div></section>`;}

function journey(){if(state.view==='fulljourney')return approvedMap();return `<section class="sn-map-section sn-workshop-guide"><iframe class="sn-approved-frame" title="Workshop 五阶段讲解" src="./workshop-guide/index.html?theme=corporate&locale=${window.CTTLanguage?.locale||new URLSearchParams(location.search).get('locale')||'zh-CN'}${state.workshopChapter===null?'':'&chapter='+state.workshopChapter}" style="height:1000px" scrolling="no"></iframe></section>`;}
function hero(){const b=heroBeats[state.hero];return `<section class="sn-hero"><div class="sn-hero-heading"><span class="sn-eyebrow">One synthetic case</span><h1>One case.<br>Every person’s part in it.</h1><p>Entity A · Australia · FX forward</p></div><div class="sn-case-facts"><span><b>Applicant</b>Entity A, Australia</span><span><b>Reported parent</b>Entity B, Singapore</span><span><b>Contributor</b>Person T, employed by B</span><span><b>Open question</b>Specific authority for A</span></div><div class="sn-hero-story"><nav aria-label="Hero case chapters">${heroBeats.map((x,i)=>btn(`<span>${String(i+1).padStart(2,'0')}</span><b>${x.title}</b><small>${x.stage}</small>`,'beat',i,`aria-current="${i===state.hero?'step':'false'}"`)).join('')}</nav><article class="sn-hero-beat"><img class="sn-hero-image" src="./studio-next/assets/${b.scene}.jpg" alt="Synthetic illustration of ${esc(b.title)}"><div class="sn-hero-copy"><span class="sn-eyebrow">${b.stage}</span><h2>${b.title}</h2><p>${b.text}</p><div class="sn-people">${b.people.map(p=>portrait(p,true)).join('')}</div><h3>${b.question}</h3><p>${b.wait}</p><div class="sn-hero-links">${b.next.map(id=>btn(esc(C.scenes.find(s=>s.id===id).title),'scene',id)).join('')}</div></div><footer>${btn('← Previous','beat',Math.max(0,state.hero-1),state.hero===0?'disabled':'')}${btn(state.hero===4?'Back to journey':'Next chapter →',state.hero===4?'view':'beat',state.hero===4?'journey':state.hero+1,'class="sn-primary"')}</footer></article></div><p class="sn-quiet">Chapters guide the story. They do not approve work or change the case.</p></section>`;}
function filtered(){const q=state.query.toLowerCase();return C.scenes.filter(s=>(state.stage==='all'||s.journey_stage===state.stage)&&(state.role==='all'||s.personas.includes(state.role))).map(s=>({...s,matches:s.parent_ids.filter(id=>{const p=P[id],a=C.actions.filter(a=>a.parent_ref===id);return (state.process==='all'||p.qualified_process_refs.some(r=>new RegExp('(?:^|[^A-Z0-9])'+state.process+'(?:[. /]|$)').test(r)))&&(state.principle==='all'||!!C.principles.find(x=>x.change_id===id)?.principle_links[state.principle])&&(state.review==='all'||(C.conflicts.some(c=>c.parent_id===id)?'pending':'aligned')===state.review)&&(state.direction==='all'||p.solution_direction===state.direction)&&(state.execution==='all'||p.execution_types.includes(state.execution))&&(!q||searchable(JSON.stringify([s.title,s.id,p,...a])).toLowerCase().includes(q));})})).filter(s=>s.matches.length);}
function index(){const hits=filtered();return `<section class="sn-index"><div class="sn-page-heading"><div><h1>Find a scenario or a piece of work</h1><p>Browse by a person’s goal, or search a name, phrase or ID.</p></div><a href="./studio-next/static.html">Print catalogue ↗</a></div><div class="sn-search-row"><label>Search<input type="search" data-sn-input="query" value="${esc(state.query)}" placeholder="Try Person T, evidence or D3-MATCH-02"></label><label>Stage<select data-sn-change="stage">${['all',...stages].map(v=>`<option ${state.stage===v?'selected':''} value="${v}">${v==='all'?'All stages':v}</option>`).join('')}</select></label><label>Person<select data-sn-change="role"><option value="all">Everyone</option>${C.personas.map(p=>`<option value="${p.id}" ${state.role===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label>${btn('Clear filters','clear-filters')}</div><details class="sn-filter-more"><summary>More filters</summary><div class="sn-search-row"><label>Solution direction<select data-sn-change="direction">${['all','retain','remove','enhance','add'].map(v=>`<option value="${v}" ${state.direction===v?'selected':''}>${v==='all'?'All directions':labels[v]}</option>`).join('')}</select></label><label>Execution<select data-sn-change="execution">${['all','Rule','Workflow','Deterministic Skill','Semantic Skill','Bounded Agent candidate','Human'].map(v=>`<option value="${v}" ${state.execution===v?'selected':''}>${v==='all'?'All types':v}</option>`).join('')}</select></label><label>Process<select data-sn-change="process">${['all',...process,'C1','C2'].map(v=>`<option value="${v}" ${state.process===v?'selected':''}>${v==='all'?'All process anchors':v}</option>`).join('')}</select></label><label>Workbook principle<select data-sn-change="principle">${['all','WB-P01','WB-P02','WB-P03','WB-P04','WB-P05','WB-P06','WB-P07'].map(v=>`<option value="${v}" ${state.principle===v?'selected':''}>${v==='all'?'All principles':v}</option>`).join('')}</select></label><label>Direction reconciliation<select data-sn-change="review">${[['all','All source judgments'],['pending','Needs review'],['aligned','No vocabulary difference']].map(([v,t])=>`<option value="${v}" ${state.review===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="sn-quiet">WB-P01–07 are local handles for the workbook README rules. They are not original Excel IDs or PX identifiers.</p></details><p class="sn-result-count" role="status">${hits.length} scenarios · ${hits.reduce((n,s)=>n+s.matches.length,0)} work items</p><div class="sn-index-results">${hits.length?hits.map(s=>`<section class="sn-index-scenario"><div><span class="sn-eyebrow">${s.journey_stage}</span><h2>${btn(esc(s.title),'scene',s.id)}</h2>${trace(s.id)}</div><div>${s.matches.map(id=>{const p=P[id],matchA=state.query?C.actions.filter(a=>a.parent_ref===id&&searchable(`${a.action_ref} ${a.action_title_en}`).toLowerCase().includes(state.query.toLowerCase())):[];return `<div class="sn-index-work">${btn(`<span>${esc(p.title_en)}</span>${trace(id)}`,'work',id)}${matchA.map(a=>btn(`<span>${esc(a.action_title_en)}</span>${trace(a.action_ref)}`,'action',a.action_ref,'class="sn-index-action"')).join('')}</div>`;}).join('')}</div></section>`).join(''):`<div class="sn-empty"><h2>No matching work</h2><p>Try a broader phrase or clear the filters.</p>${btn('Clear filters','clear-filters')}</div>`}</div></section>`;}
function research(){const refs=C.references.filter(r=>(state.filter==='all'||r.group===state.filter)&&(!state.query||searchable(`${r.name} ${r.id} ${r.borrow}`).toLowerCase().includes(state.query.toLowerCase())));return `<section class="sn-research"><div class="sn-page-heading"><div><h1>Research behind the design</h1><p>Start with the original context, then see where the idea is used.</p></div></div><div class="sn-search-row"><label>Search references<input type="search" data-sn-input="query" value="${esc(state.query)}" placeholder="Find a case, standard or pattern"></label><label>Type<select data-sn-change="filter">${[['all','All references'],['cases','Company and product cases'],['standards','Standards and guidance'],['patterns','Internal and cross-industry patterns']].map(([v,t])=>`<option value="${v}" ${state.filter===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="sn-result-count">${refs.length} references</p><div class="sn-reference-list">${refs.map(r=>`<article><span class="sn-eyebrow">${r.group==='cases'?'Case':r.group==='standards'?'Standard / guidance':'Design pattern'}</span><h2>${btn(esc(r.name),'reference',r.id)}</h2><p>${esc(r.borrow)}</p><footer><span>${r.scenarios.length} scenario links</span>${btn('Explore reference →','reference',r.id)}</footer></article>`).join('')||'<p>No references match this search.</p>'}</div></section>`;}
export function studioNextHtml(){init();return `<main id="main" class="sn-root"><div class="sn-studio-bar" ${state.view==='fulljourney'?'hidden':''}>${viewNav()}<span class="sn-quiet">Customer Journey Studio</span></div><div id="sn-content">${state.view==='flows'?flowLibrary():state.view==='product'||state.view==='workshop'?moduleView():state.view==='hero'?hero():state.view==='index'?index():state.view==='research'?research():journey()}</div><${state.view==='fulljourney'?'dialog':'section'} id="sn-panel" class="sn-panel" aria-label="Selected scenario or journey detail"><div class="sn-placeholder"><h2>Follow a scenario below the journey</h2><p>Select a scenario to see its flow, then open each piece of work.</p></div></${state.view==='fulljourney'?'dialog':'section'}><footer class="sn-footer"><span>Confidential Australian Banking Client</span><span>Synthetic design · for discussion</span><a href="./studio-next/static.html">Static catalogue</a></footer><div class="sn-status sr-only" aria-live="polite"></div></main>`;}
function flowDiagram(s){const ch=s.chapters[state.chapter]||s.chapters[0];const chart=side=>`<div class="sn-chart" data-side="${side}" data-layer="source" style="width:${state.zoom*100}%;${state.fit?'min-width:0':''}"><h3>${side==='before'?'Before':'After'}</h3>${side==='after'?workshopFlow(ch.files.after,C.diagrams[ch.files.after]):C.diagrams[ch.files.before]||'<p>The diagram is unavailable. Use the numbered work list below.</p>'}</div>`;return `${state.side==='after'||state.compare?workshopTools(ch.files.after,C.diagrams[ch.files.after]):''}<div class="sn-flow-controls">${sideButtons()}${btn('Compare','compare','',`aria-pressed="${state.compare}"`)}<label class="sn-chapter-label">Part<select data-sn-change="chapter">${s.chapters.map((c,i)=>`<option value="${i}" ${state.chapter===i?'selected':''}>${i+1} · ${esc(P[c.parents[0]].title_en)}</option>`).join('')}</select></label><div class="sn-zoom">${btn('−','zoom','out','aria-label="Zoom out"')}${btn('Fit','zoom','fit')}${btn('+','zoom','in','aria-label="Zoom in"')}</div></div><div class="sn-flow-viewport" tabindex="0" aria-label="Workflow diagram; drag or scroll to pan">${state.compare?chart('before')+chart('after'):chart(state.side)}</div><div class="sn-work-rail" aria-label="Numbered work items">${ch.parents.map((id,i)=>btn(`<b>${state.chapter*4+i+1}</b><span>${esc(P[id].title_en)}</span>`,'work',id,`aria-pressed="${state.work===id}"`)).join('')}</div>`;}
function relevantRefs(p){const wb=C.sourceWorkbook.pain_opp[p.parent_ref];const direct=C.references.filter(r=>(wb?.refs||[]).includes(r.name)||((wb?.ref_urls||[]).includes(r.source)));return direct.length?direct:C.references.filter(r=>r.scenarios.includes(p.scenario_ref)).slice(0,3);}
function referenceInline(p){const refs=relevantRefs(p);return `<section class="sn-adoption"><h4>Ideas behind this approach</h4>${refs.slice(0,3).map(r=>`<div class="sn-adoption-row"><div><b>${esc(r.name)}</b><p>${esc(r.borrow)}</p></div>${btn('Explore →','reference',r.id)}</div>`).join('')}<details><summary>All linked references</summary>${refs.map(r=>btn(esc(r.name),'reference',r.id)).join('')}<p class="sn-quiet">Work-level source associations are retained. A link is not proof that a whole product or standard validates this action.</p></details></section>`;}
function experience(p,a){const conflict=C.conflicts.find(c=>c.parent_id===p.parent_ref);return `<div class="sn-experience-pair"><section><span class="sn-eyebrow">Before</span><h4>What makes the work difficult</h4><p>${esc(p.pain_en)}</p><details><summary>The current work</summary><p>${esc(p.as_is_en)}</p></details></section><section><span class="sn-eyebrow">After · proposed</span><h4>A better experience for the person</h4><p>${esc(p.opportunity_en)}</p><details><summary>The proposed work</summary><p>${esc(p.to_be_en)}</p></details></section></div><section class="sn-solution"><div><span class="sn-key sn-${p.solution_direction}"><b>${symbols[p.solution_direction]}</b>${labels[p.solution_direction]}</span>${conflict?'<span class="sn-review-label">Direction under review</span>':''}</div><h4>${p.solution_direction==='remove'?'Remove the repeated effort':p.solution_direction==='retain'?'Keep the necessary responsibility':p.solution_direction==='add'?'Add the missing support':'Make the work easier to carry through'}</h4><p>${esc(p.solution_en)}</p>${p.remove_target?`<p><b>Remove:</b> ${esc(p.remove_target)}</p>`:''}<p class="sn-boundary">${esc(p.solution_boundary_en)}</p>${conflict?`<details><summary>Why the direction needs review</summary><p>The workbook proposes ${esc(conflict.excel_direction)}. The existing flow analysis proposes ${esc(labels[conflict.r04_direction])}. These can refer to different targets within the same work; both source judgments are retained.</p>${trace(conflict.excel_source)}</details>`:''}</section>${a?`<section class="sn-action-experience"><h4>${esc(a.action_title_en)}</h4><p class="sn-quiet">This action shares the work item’s Before context and opportunity.${a.execution_type==='Human'?' The human decision remains with the appropriate person.':''}</p></section>`:''}${referenceInline(p)}`;}
function detail(p,a){const actions=C.actions.filter(a=>a.parent_ref===p.parent_ref);return `<section class="sn-deep" id="sn-work-detail"><nav class="sn-detail-tabs" aria-label="Work detail views">${[['experience','Experience & solution'],['details','Details'],['evidence','Sources']].map(([v,t])=>btn(t,'tab',v,`aria-pressed="${state.tab===v}"`)).join('')}</nav>${state.tab==='experience'?experience(p,a):state.tab==='details'?`<div class="sn-technical"><h4>People and preparation</h4><p>${esc(p.execution_types.join(' · '))}</p><p>${esc(p.solution_boundary_en)}</p>${a?`<h4>${esc(a.action_title_en)}</h4><p>${esc(a.execution_type)} · ${esc(a.role_context_inherited)}</p><p>${esc(a.action_work_en)}</p><dl><dt>Inputs</dt><dd data-i18n-source>${esc(a.reads.join(' · '))}</dd><dt>Outputs</dt><dd data-i18n-source>${esc(a.outputs.join(' · '))}</dd><dt>Workflow</dt><dd>${esc(a.workflow_ref)}</dd><dt>Skills</dt><dd>${esc(a.skill_refs.join(' · '))}</dd><dt>Potential recipient</dt><dd>${esc(a.handoff_candidates.join(' · '))}</dd></dl>${actionWorkbook(a)}`:'<p>Select a detailed action below for its inputs and handoff.</p>'}<details><summary>Proposed product fields</summary><p>Current UI is not provided in the process deck. These are proposed fields.</p><p data-i18n-source>${esc(C.sourceWorkbook.pain_opp[p.parent_ref]?.fields.join(' · '))}</p>${trace(p.d5_surface)}<p>Exact action binding: design only.</p>${p.scenario_ref==='SCN-MATCH'?btn('Open screening workspace','product','screening'):''}</details></div>`:`<div class="sn-technical"><h4>What supports this work</h4><p>${esc(p.pain_attribution_limit)}</p><p>${esc(p.qualified_process_refs.join(' · '))}</p><details><summary>Before / After source mapping</summary>${p.source_change_relations.map(r=>`<p><b>${esc(r.semantic_type)}</b> · ${esc(r.relationship_labels.map(v=>({'可能改写/移交（未确认）':'Possible rewrite or handoff — unconfirmed','显式展开':'Explicit expansion','动作改写':'Action wording revised'}[v]||v)).join(', '))}<br>${esc(r.current_source_refs.join(' · '))}<br>${esc(r.target_source_refs.join(' · '))}</p>`).join('')}</details><details><summary>Workbook principles and exact source rows</summary>${principleDetails(p)}</details><details><summary>Original IDs and source wording</summary><p>${esc(p.original_pain_ref)} · ${esc(p.original_opportunity_refs.join(' · '))}</p><p lang="zh-CN">${esc(C.sourceWorkbook.pain_opp[p.parent_ref]?.pain)}</p></details><a href="./studio-next/parent-ledger.en.json">Open source ledger</a></div>`}<details class="sn-actions" ${a?'open':''}><summary>Detailed actions (${actions.length})</summary><div>${actions.map(x=>btn(`<span>${esc(x.action_title_en)}</span>${trace(x.action_ref)}`,'action',x.action_ref,`aria-pressed="${state.action===x.action_ref}"`)).join('')}</div></details><p class="sn-quiet">Human experience is a design hypothesis, not an interview finding.</p></section>`;}
function actionWorkbook(a){const sh=C.sourceRows['04_AI_Atomic_Detail'];const row=sh.rows.find(r=>r.cells.some(c=>c.cell.startsWith('A')&&c.value===a.action_ref));if(!row)return '';const get=col=>row.cells.find(c=>c.cell===`${col}${row.row}`)?.value;return `<details><summary>Conditions and simpler baseline</summary><p>Inputs, source versions and the relevant read/action permissions must be available. Missing requirements or unknown authority keep the affected work pending.</p><p>Resume only after the relevant evidence or authorized decision arrives, then recheck current versions and permissions.</p><p>${a.execution_type==='Human'?'Human judgment and confirmation remain with the authorized person.':a.execution_type==='Bounded Agent candidate'?'A bounded agent remains a candidate; runtime tests have not been executed.':'Use the simpler defined rule or skill where it is sufficient.'}</p>${trace(`04_AI_Atomic_Detail!A${row.row}:AG${row.row}`)}<details><summary>Original condition wording</summary><p lang="zh-CN">${esc(get('Z'))}</p><p lang="zh-CN">${esc(get('AA'))}</p><p lang="zh-CN">${esc(get('AB'))}</p></details></details>`;}
function principleDetails(p){const links=C.principles.find(x=>x.change_id===p.parent_ref);const names=['Trace the whole journey','Respect the human pain evidence','Name the proposed change','Keep execution and authority distinct','Separate known UI from proposed fields','Explain the reference before transferring it','Leave unmade media empty'];return '<p>WB-P01–07 are local review handles for README rules; original Excel and PX IDs are unchanged.</p>'+names.map((n,i)=>`<p><b>${n}</b><br>${trace(`WB-P0${i+1} · ${[].concat(links?.principle_links[`WB-P0${i+1}`]||[]).join(' · ')}`)}</p>`).join('');}
function scenarioModal(s){const mapping=getScenarioMapping(s.id);return `<div class="sn-modal-intro sn-modal-intro-text"><div><span class="sn-eyebrow">${mapping?.number||""} · ${s.journey_stage==='Clear'?'Confirm readiness':s.journey_stage} · Scenario</span><h2 id="sn-detail-title" tabindex="-1">${esc(mapping?.title||s.title)}</h2><p>${esc(s.situation)}</p>${trace(s.id)}<div class="sn-people">${s.personas.map(p=>portrait(p,true)).join('')}</div></div></div>${s.id==='SCN-SCOPE'?`<div class="sn-scope-context"><strong>Initiate · M0–M1</strong><span>Booking context → Capture once · Relationship Manager / KYC Operations</span>${btn('Locate in customer journey','locate-cj','intake')}${btn('Open Hero case','hero-case')}</div>`:''}${scenarioMappingHtml(s.id)}<section class="sn-scenario-flow" id="sm-existing-workflow" tabindex="-1"><div class="sn-flow-heading"><h3>Explore the workflow</h3>${legend()}</div>${flowDiagram(s)}</section><section class="sn-workflows"><div class="sn-workflows-heading"><h3>Then, explore the work</h3><p>Open a step to compare the person’s experience and the proposed solution.</p></div><ol class="sn-workflow-list">${s.parent_ids.map((id,i)=>{const p=P[id],selected=state.work===id;return `<li><span class="sn-work-number">${String(i+1).padStart(2,'0')}</span><details class="sn-workflow" data-work="${id}" ${selected?'open':''}><summary data-sn="workflow" data-sn-value="${id}" aria-label="${esc(p.title_en)}; ${id}"><div class="sn-step-who">${portrait(p.diagram_persona_ref||p.reading_persona_ref,true)}</div><div class="sn-step-title"><h4>${esc(p.title_en)}</h4>${trace(id)}</div><span class="sn-expand-label">${selected?'Collapse −':'Explore +'}</span></summary>${selected?detail(p,A[state.action]):''}</details></li>`;}).join('')}</ol></section><details class="sn-flow-note"><summary>Reading order and source relationships</summary><p>The numbered spine follows the authored workflow reading order. It does not by itself establish a dependency or a bank permission.</p><p>Conflicts may start from intake in both versions. Legal and Credit remain parallel; C2.6 supplies a particular input to C1.4.</p><a href="./studio-next/static.html#${s.id}">Complete printable comparison</a></details>`;}
function referenceModal(r){return `<article class="sn-ref-detail"><span class="sn-eyebrow">${r.group==='cases'?'Reference case':r.group==='standards'?'Standard or guidance':'Reference pattern'}</span><h2 id="sn-detail-title" tabindex="-1">${esc(r.name)}</h2><div class="sn-ref-sections"><section><h3>${r.group==='standards'?'Issuer and context':'Company and context'}</h3><p>${esc(r.context||r.name)}</p></section><section><h3>Departments and participants</h3><p>${esc(r.org||'Participants depend on the original source scope; no bank organization is inferred.')}</p></section><section><h3>Original journey and process</h3><p>${esc(r.journey||'This reference supports a particular practice rather than a complete customer journey.')}</p>${r.process?`<p>${esc(r.process)}</p>`:''}</section><section><h3>What we can learn</h3><p>${esc(r.borrow)}</p><p class="sn-muted">${esc(r.boundary)}</p></section><section><h3>Where this is used</h3><p>${state.work&&R[r.id]?.scenarios.includes(P[state.work]?.scenario_ref)?`Linked from ${esc(P[state.work].title_en)}. ${trace(state.work)}`:'Scenario-level associations from the mapping workbook.'}</p><div class="sn-ref-adoptions">${r.scenarios.map(id=>btn(esc(C.scenes.find(s=>s.id===id)?.title||id),'scene',id)).join('')}</div></section></div>${r.recording?'<section class="sn-recording"><span aria-hidden="true">▹</span><div><h3>Recording to be added</h3><p>This space is reserved for the case walkthrough.</p></div></section>':''}<details><summary>Source and qualification</summary><p>${esc(r.verification)}</p>${trace(r.id)}${String(r.source||'').startsWith('https://')?`<p><a href="${esc(r.source)}" target="_blank" rel="noopener">Open source ↗</a></p>`:`<p>${esc(r.source||'Internal reference. No public source link registered.')}</p>`}</details></article>`;}
function personaModal(p){return `<article class="sn-persona-detail"><div>${portrait(p.id)}<h2 id="sn-detail-title" tabindex="-1">${esc(p.name)}</h2><p>${esc(p.bio)}</p></div><dl><dt>Responsibility</dt><dd>${esc(p.responsibility)}</dd><dt>Goal</dt><dd>${esc(p.goal)}</dd><dt>Pain points</dt><dd>${p.pains.map(v=>`<p>${esc(v)}</p>`).join('')}</dd><dt>Opportunity</dt><dd>${esc(p.opportunity)}</dd><dt>Expectations</dt><dd>${p.expectations.map(v=>`<p>${esc(v)}</p>`).join('')}</dd></dl><h3>Where this person participates</h3><div class="sn-ref-adoptions">${C.scenes.filter(s=>s.personas.includes(p.id)).map(s=>btn(esc(s.title),'scene',s.id)).join('')}</div><details><summary>Profile basis</summary><p>${esc(p.status)}</p><p>${esc(p.source?.source_support_refs?.join(' · '))}</p>${trace(p.id)}</details></article>`;}
function modalContent(){if(state.reference)return referenceModal(R[state.reference]);if(state.persona)return personaModal(person(state.persona));if(state.special==='legend')return `<h2 id="sn-detail-title" tabindex="-1">One change vocabulary</h2><p>Retain the work that remains necessary. Remove a specifically identified repeated effort. Enhance how people complete existing work. Add a missing capability or support.</p><p>Blue highlights the change, with words and symbols alongside it. A move between people or lanes does not mean the work was deleted.</p><details><summary>Source change, solution direction and execution</summary><p>The flow colors show source-qualified process change. The solution explanation has its own scoped direction. Rule, Workflow, Skill, Agent candidate and Human describe who or what does the work.</p><p>Reassignment, split, merge and resequencing are mapping relationships. Unconfirmed changes carry a question marker.</p></details>`;if(state.special==='connections')return `<h2 id="sn-detail-title" tabindex="-1">Read the handoffs</h2><div class="sn-connections"><p><b>Early start</b><br>Conflicts can start from M1 intake information in Current and Target.</p><p><b>Parallel work</b><br>Legal and Credit proceed on their own available inputs and conditions.</p><p><b>A specific handoff</b><br>Credit agreement information at C2.6 feeds Legal at C1.4.</p><p><b>A proposed return loop</b><br>Review a match → request permitted missing facts → assess the response → return to the same review. Identity and coordination authority remain separate purposes.</p></div>`;if(state.special==='process')return `<h2 id="sn-detail-title" tabindex="-1">The process overview</h2>${sideButtons()}<div class="sn-macro"><img src="./studio-next/process/CTT_${state.side==='before'?'Current':'Target'}_Process_Redraw.svg" alt="${state.side==='before'?'Current':'Target'} process, reused from the Round1 source package"></div><p>Original Round1 redraw. Open at full size to inspect the source numbering.</p><a target="_blank" href="./studio-next/process/CTT_${state.side==='before'?'Current':'Target'}_Process_Redraw.svg">Open full diagram ↗</a>`;if(state.special?.startsWith('CT-')){const t=C.clientTouchpoints.find(t=>t.id===state.special);return `<h2 id="sn-detail-title" tabindex="-1">${esc(t.ask_en)}</h2><section class="sn-touchpoint-flows"><h3>Related workflows</h3><p>Select a workflow to view its diagram and detailed steps.</p><div class="sn-touchpoint-flow-links">${(t.linked_scenarios||[]).map(id=>C.scenes.find(s=>s.id===id)).filter(Boolean).map(s=>btn('<span>'+esc(s.id.replace('SCN-',''))+'</span> · <span>'+esc(s.title)+'</span>','scene',s.id)).join('')}</div></section><h3>What the person sees</h3><p>${esc(t.sees_en)}</p><h3>What they wait for</h3><p>${esc(t.waits_for_en)}</p><h3>Opportunity</h3><p>${esc(t.opportunity_en)}</p><details><summary>Source and comparison</summary><p>${esc(t.target_as_drawn_en)}</p><p>Client experience wording is a design hypothesis.</p>${trace(t.id+' · '+t.process_anchor)}</details>`;}if(scene())return scenarioModal(scene());return `<h2 id="sn-detail-title" tabindex="-1">Work not found</h2><p>The requested ID is not in this catalogue.</p>${btn('Open index','view','index')}`;}
function hasModal(){return !!(state.scene||state.persona||state.reference||state.special);}
function updateModal(focus=false){syncApprovedMap();const hiddenPanel=root?.querySelector('#sn-panel');if(hiddenPanel)hiddenPanel.hidden=['product','workshop'].includes(state.view)||(['journey','fulljourney'].includes(state.view)&&!hasModal());if(hiddenPanel?.hidden){if(hiddenPanel.open)hiddenPanel.close();return;}const panel=document.querySelector('#sn-panel');if(!panel)return;const oldY=scrollY,v=panel.querySelector('.sn-flow-viewport'),xy=[v?.scrollLeft||0,v?.scrollTop||0];if(!hasModal()){panel.classList.remove('is-open');panel.innerHTML='<div class="sn-placeholder"><h2>Follow a scenario below the journey</h2><p>Select a scenario to see its flow, then open each piece of work.</p></div>';drawLinks();return;}panel.classList.add('is-open');if(panel.tagName==='DIALOG'&&!panel.open)panel.showModal();panel.innerHTML=`<header class="sn-panel-bar"><div>${btn(state.mappingView==='scenarios'?'↑ Back to scenarios':state.view==='hero'?'↑ Back to hero journey':'↑ Back to journey','panel-top')}${state.reference&&state.scene?btn('← Back to workflow','back-reference'):''}</div><div>${scene()&&!state.reference&&!state.persona&&!state.special?btn('Print scenario','print-scene'):''}${btn('Collapse ×','close','','aria-label="Collapse detail and return"')}</div></header><div class="sn-panel-body">${modalContent()}</div>`;const nv=panel.querySelector('.sn-flow-viewport');if(nv){nv.scrollLeft=xy[0];nv.scrollTop=xy[1];}panel.querySelectorAll('.sf-node').forEach(n=>{n.classList.toggle('selected',n.dataset.parent===state.work);n.setAttribute('aria-pressed',String(n.dataset.parent===state.work));});bindPan();drawLinks();if(focus){if(panel.tagName==='DIALOG')panel.scrollTop=0;else panel.scrollIntoView({block:'start',behavior:'instant'});panel.querySelector('#sn-detail-title')?.focus({preventScroll:true});}else window.scrollTo(0,oldY);}
function storeCamera(){const m=document.querySelector('.sn-map-scroll');if(m){state.mapX=m.scrollLeft;state.mapY=m.scrollTop;}state.windowY=window.scrollY;}
function push(replace=false){const q=new URLSearchParams(location.search);q.set('studio',state.view);q.set('locale',window.CTTLanguage?.locale||new URLSearchParams(location.search).get('locale')||'en-US');for(const [k,v] of Object.entries({mapview:state.view==='fulljourney'?state.mappingView:null,mappingstage:state.mappingView==='scenarios'?state.mappingStage:null,mapquery:state.mappingView==='scenarios'&&state.mappingQuery?state.mappingQuery:null,dimension:state.view==='fulljourney'?state.dimension:null,scenario:state.scene,work:state.work,action:state.action,comparison:state.side,reference:state.reference,persona:state.persona,beat:state.view==='journey'?state.workshopChapter:(state.view==='hero'||state.view==='fulljourney'&&state.dimension==='hero')?state.hero:null}))if(v!==null&&v!==undefined)q.set(k,v);else q.delete(k);const url=`${location.pathname}?${q}`;history[replace?'replaceState':'pushState']({...history.state,sn:structuredClone(state)},'',url);lastUrl=url;}
function redraw(){if(!root?.isConnected)return;const oldPanel=root.querySelector('#sn-panel'),tag=state.view==='fulljourney'?'dialog':'section';if(oldPanel&&oldPanel.localName!==tag){const next=document.createElement(tag);next.id='sn-panel';next.className='sn-panel';next.setAttribute('aria-label','Selected scenario or journey detail');oldPanel.replaceWith(next);}root.querySelector('#sn-content').innerHTML=state.view==='flows'?flowLibrary():state.view==='product'||state.view==='workshop'?moduleView():state.view==='hero'?hero():state.view==='index'?index():state.view==='research'?research():journey();const bar=root.querySelector('.sn-studio-bar');bar.hidden=state.view==='fulljourney';bar.innerHTML=`${viewNav()}<span class="sn-quiet">Customer Journey Studio</span>`;const header=document.querySelector('.sn-app-header');if(header)header.outerHTML=studioNextHeader();const m=root.querySelector('.sn-map-scroll');if(m){m.scrollLeft=state.mapX;m.scrollTop=state.mapY;}updateModal();linkObserver?.disconnect();if(root.querySelector('.sn-matrix'))linkObserver?.observe(root.querySelector('.sn-matrix'));scheduleLinks();}
function close(){const returnToMap=state.view==='fulljourney'&&state.mappingView!=='scenarios';const selection=state.scene?{kind:'scene',id:state.scene}:state.persona?{kind:'persona',id:state.persona}:{kind:'touchpoint',id:state.special};state={...state,scene:null,work:null,action:null,reference:null,persona:null,special:null};push();updateModal();if(returnToMap){const frame=root.querySelector('.sn-approved-frame');frame?.contentWindow?.postMessage({channel:'ctt-approved-map',type:'selection',...selection},location.origin);frame?.contentWindow?.postMessage({channel:'ctt-approved-map',type:'focus'},location.origin);return;}const found=opener?.isConnected?opener:root.querySelector('.sn-view-nav button[aria-current=page]');found?.focus({preventScroll:true});found?.scrollIntoView({block:'center',behavior:'instant'});}
function chooseWork(id,action=null){const p=P[id];if(!p)return;state={...state,scene:p.scenario_ref,work:id,action,reference:null,persona:null,special:null,chapter:Math.max(0,C.scenes.find(s=>s.id===p.scenario_ref).chapters.findIndex(c=>c.parents.includes(id))),tab:'experience'};push();updateModal();requestAnimationFrame(()=>{const el=root.querySelector(`[data-work="${id}"]`);el?.scrollIntoView({block:'start',behavior:'instant'});el?.querySelector('summary')?.focus({preventScroll:true});});}
function bindPan(){const vp=root.querySelector('.sn-flow-viewport');if(!vp)return;let start;vp.addEventListener('pointerdown',e=>{if(e.target.closest('.sf-node')||e.button!==0)return;start=[e.clientX,e.clientY,vp.scrollLeft,vp.scrollTop];vp.setPointerCapture(e.pointerId);});vp.addEventListener('pointermove',e=>{if(start){vp.scrollLeft=start[2]-(e.clientX-start[0]);vp.scrollTop=start[3]-(e.clientY-start[1]);}});vp.addEventListener('pointerup',()=>start=null);vp.addEventListener('pointercancel',()=>start=null);}
export function syncStudioNextPop(s){state={...defaultState(),...s,mappingView:'map'};if(state.view==='hero'){state.view='journey';state.workshopChapter=workshopChapter(state.hero);}redraw();window.scrollTo(0,state.windowY||0);}
export function mountStudioNext(options={}){init();bridge=options;controller?.abort();controller=new AbortController();root=document.querySelector('.sn-root');if(!root)return;const opts={signal:controller.signal};bindApprovedMap(opts);bindModule(opts);bindFlowEditor(root,()=>updateModal(),opts);root.addEventListener('cancel',e=>{if(e.target.id==='sn-panel'){e.preventDefault();close();}}, {...opts,capture:true});document.documentElement.lang='en';document.body.classList.add('sn-active');if(!history.state?.sn||(state.view==='fulljourney'&&new URLSearchParams(location.search).get('mapview')!==state.mappingView))push(true);else lastUrl=location.pathname+location.search;const click=e=>{
 const preview=e.target.closest('[data-sm-preview]');if(preview){const flow=root.querySelector('#sm-existing-workflow');flow?.scrollIntoView({block:'start',behavior:'instant'});flow?.focus({preventScroll:true});return;}
 const view=e.target.closest('[data-sm-view]');if(view){state.mappingView=view.dataset.smView;state.scene=null;state.work=null;state.action=null;push();redraw();return;}
 const stage=e.target.closest('[data-sm-stage]');if(stage){state.mappingStage=stage.dataset.smStage;push();root.querySelector('.sm-explorer-content').innerHTML=mappingDirectoryHtml(state.mappingStage,state.mappingQuery);root.querySelector(`[data-sm-stage="${state.mappingStage}"]`)?.focus({preventScroll:true});return;}
 const node=e.target.closest('.sn-chart .sf-node');if(node){chooseWork(node.dataset.parent);return;}const b=e.target.closest('[data-sn]');if(!b||b.disabled)return;const action=b.dataset.sn,v=b.dataset.snValue,inPanel=!!b.closest('#sn-panel');storeCamera();if(!hasModal())opener=b;if(action==='dimension'||action==='hero-case'||action==='locate-cj'){state={...state,view:'fulljourney',mappingView:'map',dimension:action==='hero-case'?'hero':action==='locate-cj'?'cj':v,hero:action==='hero-case'?0:state.hero,locateNode:action==='locate-cj'?v:null,scene:null,work:null,action:null,reference:null,persona:null,special:null};push();redraw();window.scrollTo(0,0);return;}if(action==='view'){state={...state,view:v==='hero'?'journey':v,mappingView:v==='fulljourney'?'map':state.mappingView,scene:null,work:null,action:null,persona:null,reference:null,special:null,query:'',filter:'all'};push();redraw();window.scrollTo(0,0);root.querySelector('h1,h2')?.focus({preventScroll:true});}
 else if(action==='scene'){state={...state,scene:v,work:null,action:null,reference:null,persona:null,special:null,chapter:0,zoom:1,fit:false,compare:false,tab:'experience'};push();updateModal(true);}
 else if(action==='workflow'){e.preventDefault();if(state.work===v){state.work=null;state.action=null;push();updateModal();}else chooseWork(v);}else if(action==='work')chooseWork(v);else if(action==='action'&&A[v])chooseWork(A[v].parent_ref,v);
 else if(action==='panel-top'){if(state.view==='fulljourney'){close();return;}root.querySelector(state.view==='hero'?'.sn-hero-journey':'.sn-map-section')?.scrollIntoView({block:'start',behavior:'instant'});}else if(action==='close')close();else if(action==='persona'){state.persona=v;state.reference=null;state.special=null;push();updateModal(true);}
 else if(action==='reference'){state.reference=v;push();updateModal(true);}
 else if(action==='back-reference'){state.reference=null;push();updateModal();if(state.work)root.querySelector(`[data-work="${state.work}"]`)?.scrollIntoView({block:'start',behavior:'instant'});}
 else if(action==='side'){state.side=v;push();updateModal();(inPanel?root.querySelector('#sn-panel'):root.querySelector('.sn-map-section'))?.querySelector(`[data-sn=side][data-sn-value=${v}]`)?.focus({preventScroll:true});}
 else if(action==='compare'){state.compare=!state.compare;push();updateModal();}
 else if(action==='tab'){state.tab=v;push();updateModal();root.querySelector(`[data-sn=tab][data-sn-value=${v}]`)?.focus({preventScroll:true});}
 else if(action==='zoom'){state.fit=v==='fit';state.zoom=v==='fit'?1:Math.max(.75,Math.min(2.5,state.zoom+(v==='in'?.25:-.25)));push(true);updateModal();}
 else if(action==='beat'){state.hero=Number(v);push();redraw();}
 else if(action==='clear-filters'){state={...state,query:'',stage:'all',role:'all',direction:'all',execution:'all',process:'all',principle:'all',review:'all'};push();redraw();}
 else if(['legend','connections','process','touchpoint'].includes(action)){state.special=action==='touchpoint'?v:action;push();updateModal(true);}
 else if(action==='product'){state.returnScene=state.scene;state.view='product';push();redraw();window.scrollTo(0,0);}
 else if(action==='print-scene'){window.open(`./studio-next/static.html?scenario=${state.scene}#${state.scene}`,'_blank','noopener');}
 };
 document.addEventListener('click',click,opts);
 document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.snChange)return;const k=el.dataset.snChange;state[k]=k==='chapter'?Number(el.value):el.value;if(k==='chapter'){state.work=null;state.action=null;push();updateModal();}else{push();redraw();}},opts);
 document.addEventListener('input',e=>{if(e.target.matches('[data-sm-search]')){state.mappingQuery=e.target.value;push(true);const host=root.querySelector('.sm-explorer-content');const wrap=document.createElement('div');wrap.innerHTML=mappingDirectoryHtml(state.mappingStage,state.mappingQuery);host.querySelector('.sm-directory-results').replaceWith(wrap.querySelector('.sm-directory-results'));return;}if(!e.target.dataset.snInput)return;const pos=e.target.selectionStart;state.query=e.target.value;push(true);redraw();const input=root.querySelector('[data-sn-input=query]');input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}},opts);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&hasModal()){e.preventDefault();close();return;}if(e.target.closest('.sn-chart .sf-node')&&['Enter',' '].includes(e.key)){e.preventDefault();chooseWork(e.target.closest('.sf-node').dataset.parent);}if(e.target.matches('[data-sn=side]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const target=e.key==='Home'?'before':e.key==='End'?'after':state.side==='before'?'after':'before';const context=e.target.closest('#sn-panel')||root.querySelector('.sn-map-section');context?.querySelector(`[data-sn=side][data-sn-value=${target}]`)?.click();}},opts);
 window.addEventListener('resize',scheduleLinks,opts);document.addEventListener('visibilitychange',scheduleLinks,opts);root.addEventListener('load',scheduleLinks,{...opts,capture:true});root.querySelector('.sn-map-scroll')?.addEventListener('scroll',scheduleLinks,{...opts,passive:true});linkObserver?.disconnect();linkObserver=new ResizeObserver(scheduleLinks);if(root.querySelector('.sn-matrix'))linkObserver.observe(root.querySelector('.sn-matrix'));scheduleLinks();
 updateModal(hasModal());
}
export function unmountStudioNext(){controller?.abort();linkObserver?.disconnect();clearTimeout(drawTimer);document.body.classList.remove('sn-active','sn-modal-open');}
export function studioNextState(){return structuredClone(state);}
// Capture Studio deep links before the host normalizes its own navigation URL.
init();

function scheduleLinks(){clearTimeout(drawTimer);requestAnimationFrame(drawLinks);drawTimer=setTimeout(drawLinks,150);}
function drawLinks(){const matrix=root?.querySelector('.sn-matrix'),svg=matrix?.querySelector('.sn-link-overlay');if(!svg)return;const m=matrix.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${m.width} ${m.height}`);svg.setAttribute('width',m.width);svg.setAttribute('height',m.height);const rect=key=>{const el=matrix.querySelector(key.startsWith('COL|')?`[data-col="${key.slice(4)}"]`:`[data-key="${key}"] .sn-scenario`);if(!el)return null;const r=el.getBoundingClientRect();return {x:r.left-m.left,y:r.top-m.top,w:r.width,h:r.height}};svg.innerHTML=LINKS.map((l,i)=>{const a=rect(l.from),b=rect(l.to);if(!a||!b)return '';let ax=a.x+a.w/2,ay=a.y+a.h/2,bx=b.x+b.w/2,by=b.y+b.h/2,d,lx,ly;
 if(l.kind==='early'){ay=a.y+a.h;bx=b.x+b.w;const y=ay+5,x=m.width-4;d=`M ${ax} ${ay} Q ${ax} ${y} ${ax+5} ${y} L ${x-5} ${y} Q ${x} ${y} ${x} ${y+5} L ${x} ${by-8} Q ${x} ${by} ${x-8} ${by} L ${bx} ${by}`;lx=bx+8;ly=by-8;}
 else if(l.from_scn==='SCN-MATCH'){ax=a.x;bx=b.x+b.w;const ch=(ax+bx)/2;d=`M ${ax} ${ay} C ${ch} ${ay}, ${ch} ${by}, ${bx} ${by}`;}
 else if(l.from_scn==='SCN-GAP'){ax=a.x;bx=b.x;const ch=Math.min(ax,bx)-8;d=`M ${ax} ${ay} C ${ch} ${ay}, ${ch} ${by}, ${bx} ${by}`;}
 else {const down=b.y>a.y;ay=down?a.y+a.h:a.y;by=down?b.y:b.y+b.h;const c=Math.max(6,Math.min(Math.abs(by-ay)*.4,40));d=`M ${ax} ${ay} C ${ax} ${ay+(down?c:-c)}, ${bx} ${by-(down?c:-c)}, ${bx} ${by}`;lx=(ax+bx)/2+12;ly=(ay+by)/2;}
 const related=!state.scene||[l.from_scn,l.to_scn].includes(state.scene),label=l.anchor||(l.kind==='early'?'From M1':'');return `<defs><marker id="sn-arrow-${i}" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#004D86"/></marker></defs><path class="${l.kind} ${related?'on':'dim'}" data-link="${i}" data-from="${l.from}" data-to="${l.to}" d="${d}" marker-end="url(#sn-arrow-${i})"><title>${esc(l.label)} · ${esc(l.limit)}</title></path>${label?`<text x="${lx}" y="${ly}" class="${related?'on':'dim'}">${esc(label)}</text>`:''}`}).join('');matrix.querySelectorAll('.sn-scenario').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.snValue===state.scene)));}

function heroHotspots(){const areas=[['SCN-SCOPE',134,154,96,39],['SCN-ENTITY',238,154,85,39],['SCN-REQUIREMENTS',133,221,98,38],['SCN-SOURCE',132,280,94,40],['SCN-GAP',238,280,58,40],['SCN-POPULATION',302,280,97,40],['SCN-MATCH',415,270,125,50],['SCN-MATCH',413,345,127,74],['SCN-MATCH',204,355,168,58],['SCN-EDD',165,455,98,44],['SCN-LEGAL',265,455,119,44],['SCN-CREDIT',388,455,108,44],['SCN-CONFLICTS',501,455,95,44],['SCN-QA',599,455,89,44],['SCN-READINESS',727,368,141,125]];return areas.map(([id,x,y,w,h])=>{const sc=C.scenes.find(s=>s.id===id);return btn(`<span>${esc(sc.title)}</span>`,'scene',id,`class="sn-hero-hotspot" style="left:${x/887*100}%;top:${y/591*100}%;width:${w/887*100}%;height:${h/591*100}%" aria-label="Open scenario: ${esc(sc.title)}; ${id}"`)}).join('');}

function syncApprovedMap(){
 const frame=root?.querySelector('.sn-approved-frame');if(!frame)return;
 const kind=state.persona?'persona':state.special?.startsWith('CT-')?'touchpoint':state.scene?'scene':null;
 frame.contentWindow?.postMessage({channel:'ctt-approved-map',type:'selection',kind,id:kind==='persona'?state.persona:kind==='touchpoint'?state.special:state.scene},location.origin);
}
function bindApprovedMap(opts){
 window.addEventListener('message',e=>{
  const frame=root?.querySelector('.sn-approved-frame');if(!frame||e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.channel!=='ctt-approved-map')return;
  const d=e.data;
  if(d.type==='locate-cj'&&typeof d.node==='string'){state.dimension='cj';state.locateNode=d.node;push();redraw();return;}
  if(d.type==='chapter'&&state.view==='journey'&&Number.isInteger(d.chapter)&&d.chapter>=0&&d.chapter<5){state.workshopChapter=d.chapter;push(true);return;}
  if(d.type==='height'&&state.view==='fulljourney')return;
  if(d.type==='height'&&Number.isFinite(d.height)&&d.height>0&&d.height<20000){const y=scrollY;frame.style.height=d.height+'px';if(hasModal()&&y>frame.getBoundingClientRect().bottom)window.scrollTo(0,y);return;}
  if(d.type==='camera'){state.mapX=Number(d.x)||0;return;}
  if(d.type==='ready'){syncApprovedMap();frame.contentWindow.postMessage({channel:'ctt-approved-map',type:'camera',x:state.mapX},location.origin);if(hasModal()&&state.view!=='fulljourney')root.querySelector('#sn-panel')?.scrollIntoView({block:'start',behavior:'instant'});return;}
  if(d.type==='close'){close();return;}
  if(d.type==='preview'&&d.kind==='scene'&&C.scenes.some(s=>s.id===d.id)){
   state={...state,scene:null,work:null,action:null,reference:null,persona:null,special:null};
   push();updateModal();
   frame.contentWindow.postMessage({channel:'ctt-approved-map',type:'selection',kind:'scene',id:d.id},location.origin);
   return;
  }
  if(d.type!=='select')return;
  if(!(d.kind==='scene'&&C.scenes.some(s=>s.id===d.id)||d.kind==='persona'&&person(d.id)||d.kind==='touchpoint'&&C.clientTouchpoints.some(t=>t.id===d.id)))return;
  storeCamera();opener=frame;
  state={...state,scene:null,work:null,action:null,reference:null,persona:null,special:null,chapter:0,zoom:1,fit:false,compare:false,tab:'experience'};
  if(d.kind==='scene')state.scene=d.id;else if(d.kind==='persona')state.persona=d.id;else state.special=d.id;
  push();updateModal(true);
 },opts);
}

function moduleView(){const product=state.view==='product';return '<section class="sn-module '+(product?'sn-product-system':'')+'"><iframe class="sn-module-frame" title="'+(product?'Interactive product demo':'Workshop scorecard — final step')+'" src="./'+(product?'product-demo':'workshop')+'/index.html'+(product&&state.returnScene?'?scenario='+state.returnScene:'')+'"></iframe></section>';}
function bindModule(opts){window.addEventListener('message',e=>{const f=root?.querySelector('.sn-module-frame');if(!f||e.source!==f.contentWindow||e.origin!==location.origin||e.data?.channel!=='ctt-module')return;const d=e.data;if(d.type==='view'&&['journey','hero','workshop','product'].includes(d.view)){state={...state,view:d.view==='hero'?'journey':d.view,scene:null,work:null,action:null,persona:null,reference:null,special:null};push();redraw();window.scrollTo(0,0);}if(d.type==='scenario'&&C.scenes.some(s=>s.id===d.id)){state={...state,view:'journey',scene:d.id,work:null,action:null,persona:null,reference:null,special:null};push();redraw();updateModal(true);}},opts);}

function flowLibrary(){return '<section class="sn-module"><iframe class="sn-module-frame" title="逐项流程全集" src="./flow-library/index.html" style="height:calc(100vh - 160px);min-height:760px"></iframe></section>';}
